import { normalizeEntities } from '../../../../admin/schema';
import apiFetch from '../../functions/fetch';
import { Price, Product } from '../../types';
import { addQueryArgs } from '@wordpress/url';

const path = 'surecart/v1/products/';

// Uses the public find route because listing prices is staff-only; archived prices are dropped as the old list did.
export const getPriceWithProduct = async (id: string) => {
  const price = (await apiFetch({
    path: addQueryArgs(`surecart/v1/prices/${id}`, {
      expand: ['product'],
    }),
  })) as Price;

  return normalizePrices(price?.archived ? [] : [price]);
};
export const normalizePrices = (prices: Array<Price>) => {
  const { entities } = normalizeEntities(prices);
  return {
    prices: entities?.price,
    products: entities?.product,
  };
};

/**
 * Get prices
 */
export const getProducts = async ({ query }: { query: Object }) => {
  return (await apiFetch({
    path: addQueryArgs(path, query),
  })) as Array<Product>;
};
